import{z as A,x as B,o as r,c as d,q as n,j as i,D as e,d as s,s as o,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"寄存器与移位","description":"","frontmatter":{"title":"寄存器与移位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/register-shift.md","filePath":"cs/register-shift.md","lastUpdated":1791063341000}'),D={name:"cs/register-shift.md"};function p(c,a,F,h,m,C){const E=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="寄存器与移位" tabindex="-1">寄存器与移位 <a class="header-anchor" href="#寄存器与移位" aria-label="Permalink to &quot;寄存器与移位&quot;">​</a></h1><div class="epigraph"><p>寄存器是并排的触发器加使能；移位则是相邻位之间的组合接线，用同一拍时钟把字滑一格。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/metastability">亚稳态与同步器</a>钉死了 FF 之间的时序不等式。本课不重写 \\(t_{su}\\)，也不从 ISA 的 <code>sll</code> 另起一张指令表。缺口是：1 比特 FF 还不是 CPU 里的「寄存器」。需要 \\(n\\) 位并列、写使能、以及作为组合/时序混合的<strong>移位</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ALU 输出要在边沿写进一组 FF，且不是每拍都写：<code>RegWrite</code> 为假时应保持。缺口是带使能的寄存器：使能接 MUX 反馈 Q，或接时钟门控（后者有自己的时序代价）。移位：逻辑左移把权乘 2（无符号），算术右移复制符号位——语义来自<a href="/cs/twos-complement">补码</a>，电路是相邻 FF 的 D 接到邻居的 Q，或纯组合桶形接到寄存器输入。</p><p>本课钉并行寄存器与移位寄存器两种。寄存器堆是后课多口阵列。</p><h3 id="移位寄存器不是桶形移位器" tabindex="-1">移位寄存器不是桶形移位器 <a class="header-anchor" href="#移位寄存器不是桶形移位器" aria-label="Permalink to &quot;移位寄存器不是桶形移位器&quot;">​</a></h3><p>移位寄存器每拍移 1 位，延迟是拍数。桶形移位器组合一拍移任意量，延迟是 MUX 树。RISC-V <code>sll</code> 要的是后者语义；串行移位是 UART、CRC 的结构。名字都叫移位，时序模型不同。</p><p><span class="marginnote">Harris 分 load-enable 寄存器与移位寄存器。Patterson/Hennessy 的寄存器是程序可见的 32 个字，实现是后课寄存器堆；本课先给 1 个字。</span></p><p><span class="marginnote">数字实例：4 位补码 \\(1110_2\\) 是 \\(-2\\)，算术右移 1 位得 \\(1111_2=-1\\)——符号位被复制，等价于除 2 向下取整；同一字做<strong>逻辑</strong>右移得 \\(0111_2=7\\)，负数瞬间变正。又如 \\(0101_2=5\\) 左移 1 位得 \\(1010_2=10\\)，每位权翻倍即乘 2。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(n\\) 个 D-FF 共享时钟。Load=1 时 D 来自总线，否则 D=Q。移位模式：每级 D 接上一级 Q，端点接串入或 0/符号。建立保持按最坏位。</p><p><span class="marginnote">直觉类比：使能寄存器像带锁的抽屉——锁没开（Load=0）时钟边沿来了也不动；串行移位寄存器像一排人传纸条，每声哨响（时钟拍）传一格。</span></p>',13)),(r(),i(l,null,{default:e(()=>[o(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20FF%5B%22D%20%E8%A7%A6%E5%8F%91%E5%99%A8%22%5D%20--%3E%20REG%5B%22n%20%E4%BD%8D%E4%BD%BF%E8%83%BD%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20REG%20--%3E%20SH%5B%22%E7%A7%BB%E4%BD%8D%E6%8E%A5%E7%BA%BF%E6%88%96%E6%A1%B6%E5%BD%A2%22%5D%0A%20%20SH%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%94%A8%E5%AF%84%E5%AD%98%E5%99%A8%E5%81%9A%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"PC 是带 +4 与跳转 MUX 的寄存器。立即数不存寄存器里也能进 ALU，那是数据通路 MUX。移位作为 ALU 功能时走组合桶形，结果再进寄存器写口；作为外设时用移位寄存器省面积。",-1)),a[5]||(a[5]=t("p",null,"时钟门控修功耗，但使能的时序要当时钟完整性处理，本课推荐 MUX 使能作为默认。",-1)),(r(),i(l,null,{default:e(()=>[o(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%228%20%E4%BD%8D%E8%BE%93%E5%85%A5%22%5D%20--%3E%20SR%5B%22%E4%B8%B2%E8%A1%8C%E7%A7%BB%E4%BD%8D%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%9A%E6%AF%8F%E6%8B%8D%E7%A7%BB%201%20%E4%BD%8D%22%5D%0A%20%20SR%20--%3E%20T3%5B%22%E7%A7%BB%203%20%E4%BD%8D%20%3D%20%E7%AD%89%203%20%E4%B8%AA%E6%97%B6%E9%92%9F%E6%8B%8D%22%5D%0A%20%20T3%20--%3E%20USE1%5B%22UART%20%2F%20CRC%EF%BC%9A%E7%9C%81%E9%9D%A2%E7%A7%AF%EF%BC%8C%E6%85%A2%22%5D%0A%20%20IN%20--%3E%20BS%5B%22%E6%A1%B6%E5%BD%A2%E7%A7%BB%E4%BD%8D%E5%99%A8%EF%BC%9A%E6%8C%89%E4%BD%8D%E5%88%86%E5%B1%82%20MUX%20%E6%A0%91%22%5D%0A%20%20BS%20--%3E%20ONCE%5B%22%E7%A7%BB%203%20%E4%BD%8D%20%3D%20%E4%B8%80%E6%8B%8D%E5%86%85%E7%BB%84%E5%90%88%E5%AE%8C%E6%88%90%22%5D%0A%20%20ONCE%20--%3E%20USE2%5B%22sll%20%2F%20sra%20%E6%8C%87%E4%BB%A4%EF%BC%9A%E5%8D%95%E5%91%A8%E6%9C%9F%E8%AF%AD%E4%B9%89%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲重命名物理寄存器、不把向量寄存器请进来。DRAM 行缓冲不是 FF 寄存器。多时钟仍未正式展开。</p><p>后课默认：一个字的状态是带写使能的并行 FF；指令移位是组合桶形加写回。</p><p><span class="marginnote">常见误区：初学者以为 <code>sll x1, x2, 3</code> 是一拍移一位、连移三拍。指令移位由桶形移位器组合实现，一个周期出结果；每拍一位的串行移位寄存器是 UART、CRC 那类外设结构——名字像，时序模型完全不同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>寄存器 = 并行 FF + 写使能。</li><li>串行移位按拍；指令移位通常是组合桶形。</li><li>算术右移复制符号位，逻辑移位补 0。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',6))])}const f=A(D,[["render",p]]);export{_ as __pageData,f as default};
